package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                            // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)     // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0)     // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0                                 // PIC 9(3) len=3 = 0
var WsIncEd string                                    // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string                                    // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string                                    // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string                                  // PIC ZZ,ZZZ,ZZ9.99 len=13

// file handling
var taxFile *os.File
var scanner *bufio.Scanner
var inputDone bool
var curRec TaxRec

func storeDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	factor := decimal.New(1, int32(scale))
	scaled := v.Mul(factor).Truncate(0)
	sign := 1
	if scaled.IsNegative() {
		sign = -1
		scaled = scaled.Abs()
	}
	pow := intDigits + scale
	modBase := decimal.New(1, int32(pow))
	mod := scaled.Mod(modBase)
	if sign == -1 {
		mod = mod.Neg()
	}
	result := mod.Shift(int32(-scale))
	return result
}

func formatPicture(v decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigitsCount := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigitsCount++
		}
	}
	fracDigitsCount := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracDigitsCount++
		}
	}
	scale := fracDigitsCount
	abs := v.Abs()
	trunc := abs.Truncate(int32(scale))

	var intStr, fracStr string
	if scale > 0 {
		s := trunc.StringFixed(int32(scale))
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		if strings.HasPrefix(intStr, "+") {
			intStr = intStr[1:]
		}
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
	} else {
		s := trunc.StringFixed(0)
		intStr = s
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		fracStr = ""
	}
	// handle overflow: keep low-order digits
	if len(intStr) > intDigitsCount {
		intStr = intStr[len(intStr)-intDigitsCount:]
	}
	if len(intStr) < intDigitsCount {
		intStr = strings.Repeat("0", intDigitsCount-len(intStr)) + intStr
	}
	if len(fracStr) < scale {
		fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
	} else if len(fracStr) > scale {
		fracStr = fracStr[:scale]
	}

	out := make([]rune, len(picture))
	// integer part
	suppressing := true
	intIdx := 0
	for i, ch := range intPic {
		switch ch {
		case ',':
			if suppressing {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		case 'Z', '9':
			digit := intStr[intIdx]
			intIdx++
			if suppressing && digit == '0' && ch == 'Z' {
				out[i] = ' '
			} else {
				suppressing = false
				out[i] = rune(digit)
			}
		default:
			out[i] = ch
		}
	}
	if dotPos >= 0 {
		out[dotPos] = '.'
		fracIdx := 0
		for i, ch := range fracPic {
			outIdx := dotPos + 1 + i
			if ch == '9' || ch == 'Z' {
				if fracIdx < len(fracStr) {
					out[outIdx] = rune(fracStr[fracIdx])
					fracIdx++
				} else {
					out[outIdx] = '0'
				}
			} else {
				out[outIdx] = ch
			}
		}
	}
	return string(out)
}

func formatCount(c int64) string {
	mod := c % 1000
	if mod < 0 {
		mod = -mod
	}
	return fmt.Sprintf("%03d", mod)
}

func parseIncomeField(field string) decimal.Decimal {
	// field len 8, digits only, implied 2 decimals
	if strings.TrimSpace(field) == "" {
		return decimal.NewFromInt(0)
	}
	cleaned := strings.ReplaceAll(field, " ", "")
	if cleaned == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits (and sign if any)
	// try direct parse
	d, err := decimal.NewFromString(cleaned)
	if err != nil {
		// filter digits
		var b strings.Builder
		for _, r := range cleaned {
			if r >= '0' && r <= '9' {
				b.WriteRune(r)
			}
			if r == '-' {
				b.WriteRune(r)
			}
		}
		if b.Len() == 0 {
			return decimal.NewFromInt(0)
		}
		d, _ = decimal.NewFromString(b.String())
	}
	return d.Shift(-2)
}

func MainPara() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer taxFile.Close()
	scanner = bufio.NewScanner(taxFile)
	// Increase buffer if needed (record is tiny, default is fine)
	ReadPara()
	for !inputDone {
		ProcessPara()
	}
	// MOVE WS-TOTAL-TAX TO WS-TOTAL-ED
	WsTotalEd = formatPicture(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsCount)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func ReadPara() {
	if scanner == nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 13 {
			line = line + strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		trId := line[0:5]
		incomeField := line[5:13]
		curRec.TrId = trId
		curRec.TrIncome = parseIncomeField(incomeField)
		WsEofFlag = "N"
		inputDone = false
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		inputDone = true
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	d10000 := decimal.NewFromInt(10000)
	d40000 := decimal.NewFromInt(40000)
	d1000 := decimal.NewFromInt(1000)
	d7000 := decimal.NewFromInt(7000)
	rate10 := decimal.New(10, -2) // 0.10
	rate20 := decimal.New(20, -2) // 0.20
	rate30 := decimal.New(30, -2) // 0.30

	var tax decimal.Decimal
	if curRec.TrIncome.Cmp(d10000) <= 0 {
		tax = curRec.TrIncome.Mul(rate10).Round(2)
	} else if curRec.TrIncome.Cmp(d40000) <= 0 {
		diff := curRec.TrIncome.Sub(d10000)
		tax = d1000.Add(diff.Mul(rate20)).Round(2)
	} else {
		diff := curRec.TrIncome.Sub(d40000)
		tax = d7000.Add(diff.Mul(rate30)).Round(2)
	}
	WsTax = storeDecimal(tax, 7, 2)

	net := curRec.TrIncome.Sub(WsTax).Truncate(2)
	WsNet = storeDecimal(net, 7, 2)

	total := WsTotalTax.Add(WsTax)
	WsTotalTax = storeDecimal(total, 9, 2)

	WsCount = WsCount + 1
	if WsCount >= 1000 || WsCount < 0 {
		WsCount = WsCount % 1000
		if WsCount < 0 {
			WsCount = -WsCount
		}
	}

	WsIncEd = formatPicture(curRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatPicture(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatPicture(WsNet, "ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s %s\n", curRec.TrId, WsIncEd, WsTaxEd, WsNetEd)

	ReadPara()
}

func main() {
	MainPara()
}
